class CartForUse {
    _carts;
    constructor() {
        this._carts = [];
    }
    addCart(cart) {
        this._carts.push(cart);
    }
    delCart(id) {
        this._carts.splice(id, 1);
    }
    getCarts() {
        return this._carts;
    }
    use() {
        this._carts.forEach((c, i, cs) => {
            c.action();
        });
        this._carts = [];
    }
}
export default CartForUse;
